\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Dark Theme Colors ──
\definecolor{bgposter}{HTML}{080D1A}      % very dark navy
\definecolor{cardbg}{HTML}{132040}        % slightly lighter card bg
\definecolor{cardtitlebg}{HTML}{1A2D56}   % card title bar bg
\definecolor{amber}{HTML}{F59E0B}         % warm amber accent
\definecolor{amberdark}{HTML}{D97706}     % darker amber
\definecolor{coral}{HTML}{F43F5E}         % coral/rose for crisis
\definecolor{coraldark}{HTML}{E11D48}     % darker coral
\definecolor{textlight}{HTML}{F1F5F9}     % main text
\definecolor{textmuted}{HTML}{94A3B8}     % muted secondary text
\definecolor{statbg}{HTML}{1C2D52}        % stat background
\definecolor{highlightbg}{HTML}{241A0A}   % warm dark tint for takeaway

\pagecolor{bgposter}
\color{textlight}

% ── List Styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{amber}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{amber}\bfseries\arabic*.}}

% ── Card Styles (dark theme, left accent stripe) ──
\tcbset{
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{amber},
    left=14pt, right=12pt, top=2pt, bottom=4pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=cardtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={amber!50},
    valign=top, drop shadow={opacity=0.35},
  },
  coralcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{coral},
    left=14pt, right=12pt, top=2pt, bottom=4pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{coral},
    coltitle=coral, colbacktitle=cardtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={coral!50},
    valign=top, drop shadow={opacity=0.35},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=highlightbg,
    borderline west={5pt}{0pt}{amber},
    left=14pt, right=12pt, top=2pt, bottom=4pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=amber!30!highlightbg,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.35},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════
% TITLE BAR (span both columns, rows 0-4)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=bgposter, colframe=bgposter, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=6pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{amber!60},
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{54}{64}\selectfont\bfseries\color{white} THE STATE OF GLOBAL EDUCATION}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{amber} Progress, Gaps, and Inequality}\\[8pt]
  {\fontsize{18}{24}\selectfont\color{textmuted} A data-driven look at two centuries of educational expansion — and the critical challenges that remain}
}

% ═══════════════════════════════════════════
% STAT BANNER (span both columns, rows 4-6)
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=16pt, right=16pt, top=8pt, bottom=8pt,
  valign=center, halign=center,
  borderline south={2pt}{0pt}{amber!30},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.28\linewidth}
    \centering
    {\fontsize{34}{42}\selectfont\bfseries\color{amber} $<$1 in 5 $\to$ $>$4 in 5}\\[6pt]
    {\fontsize{18}{24}\selectfont\color{textmuted} Adults with any formal education\\1800 $\longrightarrow$ Today}
  \end{minipage}%
  \begin{minipage}[c]{0.40\linewidth}
    \centering
    {\fontsize{60}{72}\selectfont\bfseries\color{coral} 244}\\[2pt]
    {\fontsize{20}{26}\selectfont\bfseries\color{textlight} MILLION}\\[4pt]
    {\fontsize{30}{38}\selectfont\bfseries\color{textlight} CHILDREN OUT}\\[2pt]
    {\fontsize{30}{38}\selectfont\bfseries\color{textlight} OF SCHOOL}\\[4pt]
    {\fontsize{16}{22}\selectfont\color{textmuted} Primary \& secondary education, 2023}
  \end{minipage}%
  \begin{minipage}[c]{0.28\linewidth}
    \centering
    {\fontsize{34}{42}\selectfont\bfseries\color{coral} $<$3}%
    {\fontsize{22}{30}\selectfont\bfseries\color{textlight}\quad vs\quad}%
    {\fontsize{34}{42}\selectfont\bfseries\color{amber} 10+}\\[6pt]
    {\fontsize{18}{24}\selectfont\color{textmuted} Learning-adjusted years\\Poorest \quad vs \quad Richest countries}
  \end{minipage}
}

% ═══════════════════════════════════════════
% ROW A (rows 6-11): Historical Progress + Learning Crisis
% ═══════════════════════════════════════════
\posterbox[ambercard, title={Two Centuries of Educational Expansion}
]{name=history, column=1, between=row6 and row11}{
  \fontsize{24}{32}\selectfont\color{textlight}
  In the early 1800s, fewer than \textcolor{amber}{\textbf{1 in 5}} adults worldwide had received any formal education. Education was a luxury reserved for a small elite.\par
  \vspace{10pt}
  Over two centuries, this ratio has \textcolor{amber}{\textbf{reversed dramatically}}. Today, more than \textcolor{amber}{\textbf{4 in 5}} adults have received some formal primary, secondary, or tertiary education.\par
  \vspace{12pt}
  {\centering
  \colorbox{bgposter}{\parbox{0.90\linewidth}{\centering\vspace{6pt}
    {\fontsize{22}{28}\selectfont\color{textmuted} 1800}\\[2pt]
    {\fontsize{38}{46}\selectfont\bfseries\color{coral} < 1 in 5}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{amber} $\boldsymbol\downarrow$}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textmuted} Today}\\[2pt]
    {\fontsize{38}{46}\selectfont\bfseries\color{amber} > 4 in 5}\\[2pt]
    {\fontsize{18}{24}\selectfont\color{textmuted} adults with basic education}
  \vspace{6pt}}}
}

\posterbox[coralcard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=crisis, column=2, between=row6 and row11}{
  \fontsize{24}{32}\selectfont\color{textlight}
  International statistics often track enrollment as the marker of progress. But \textcolor{coral}{\textbf{being enrolled does not guarantee quality learning}}.\par
  \vspace{10pt}
  In many lower-income countries, \textcolor{coral}{\textbf{fewer than 20\%}} of children achieve minimum reading proficiency by the end of primary school.\par
  \vspace{12pt}
  {\centering
  \colorbox{bgposter}{\parbox{0.90\linewidth}{\centering\vspace{6pt}
    {\fontsize{48}{56}\selectfont\bfseries\color{coral} < 20\%}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textmuted} achieve minimum reading proficiency}\\[4pt]
    {\fontsize{18}{24}\selectfont\color{textmuted} Cannot identify key ideas in a text\\or connect them to their own experiences}
  \vspace{6pt}}}
}

% ═══════════════════════════════════════════
% ROW B (rows 11-16): 244M Breakdown + World Divided
% ═══════════════════════════════════════════
\posterbox[coralcard, title={244 Million: The Scale of the Challenge}
]{name=outofschool, column=1, between=row11 and row16}{
  \fontsize{24}{32}\selectfont\color{textlight}
  Despite enormous progress, approximately \textcolor{coral}{\textbf{244 million}} children of official school age were not enrolled in primary or secondary education in 2023.\par
  \vspace{8pt}
  A major driver is \textcolor{coral}{\textbf{secondary-level dropout}}: many children who complete primary school do not continue.\par
  \vspace{10pt}
  {\centering
  \begin{minipage}{0.46\linewidth}
    \centering
    \colorbox{bgposter}{\parbox{0.92\linewidth}{\centering\vspace{6pt}
      {\fontsize{38}{46}\selectfont\bfseries\color{coral} \~{}60M}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Primary-age\\children}
    \vspace{6pt}}}
  \end{minipage}\hfill
  \begin{minipage}{0.50\linewidth}
    \centering
    \colorbox{bgposter}{\parbox{0.92\linewidth}{\centering\vspace{6pt}
      {\fontsize{38}{46}\selectfont\bfseries\color{coral} \~{}184M}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Secondary-age\\adolescents}
    \vspace{6pt}}}
  \end{minipage}\par}
}

\posterbox[ambercard, title={Quality Schooling: A World Divided}
]{name=divided, column=2, between=row11 and row16}{
  \fontsize{24}{32}\selectfont\color{textlight}
  Researchers combine the quantity and quality of education into a single metric: \textcolor{amber}{\textbf{learning-adjusted years of schooling}}. The disparities are enormous.\par
  \vspace{10pt}
  {\centering
  \colorbox{bgposter}{\parbox{0.92\linewidth}{\centering\vspace{8pt}
    {\fontsize{20}{26}\selectfont\color{textmuted} Poorest countries}\\[2pt]
    {\fontsize{44}{52}\selectfont\bfseries\color{coral} < 3 years}\\[4pt]
    {\color{cardbg}\rule{0.6\linewidth}{2pt}}\\[6pt]
    {\fontsize{20}{26}\selectfont\color{textmuted} High-income countries}\\[2pt]
    {\fontsize{44}{52}\selectfont\bfseries\color{amber} 10+ years}
  \vspace{6pt}}}
  \vspace{8pt}
  {\fontsize{20}{26}\selectfont\color{textmuted} Children in the world's poorest nations receive less than a third of the quality schooling available to peers in wealthy countries. Most of the world's children live in South Asia and Sub-Saharan Africa, where the average remains below 7 years.}
}

% ═══════════════════════════════════════════
% ROW C (rows 16-20): Gender Gap + Key Takeaways
% ═══════════════════════════════════════════
\posterbox[ambercard, title={Closing the Gender Gap}
]{name=gender, column=1, between=row16 and bottom}{
  \fontsize{24}{32}\selectfont\color{textlight}
  Historically, boys were far more likely to attend school than girls. Today, the \textcolor{amber}{\textbf{global gender gap in enrollment has largely closed}} across primary and secondary education. At the tertiary level, young women are now more likely to be enrolled than young men.\par
  \vspace{10pt}
  {\centering
  \colorbox{bgposter}{\parbox{0.90\linewidth}{\centering\vspace{6pt}
    {\fontsize{20}{26}\selectfont\color{textmuted} Primary \& Secondary}\\[2pt]
    {\fontsize{26}{34}\selectfont\bfseries\color{amber} Nearly closed globally}\\[8pt]
    {\fontsize{20}{26}\selectfont\color{textmuted} Tertiary}\\[2pt]
    {\fontsize{26}{34}\selectfont\bfseries\color{amber} Women now exceed men}
  \vspace{6pt}}}
  \vspace{8pt}
  {\fontsize{20}{26}\selectfont\color{textmuted}\textbf{Exception:} In countries like Afghanistan, girls remain far less likely to attend school at any level.}
}

\posterbox[highlightcard, title={The Road Ahead}
]{name=takeaway, column=2, between=row16 and bottom}{
  \fontsize{24}{32}\selectfont\color{textlight}
  \begin{itemize}[itemsep=8pt]
    \item Remarkable progress over two centuries — \textcolor{amber}{\textbf{<1 in 5 $\to$ >4 in 5}} adults now educated
    \item Yet \textcolor{coral}{\textbf{244 million}} children remain out of school — secondary dropout is the biggest driver
    \item Many enrolled children are \textcolor{coral}{\textbf{learning very little}} — <20\% achieve minimum reading proficiency
    \item The gap between \textcolor{coral}{\textbf{rich and poor}} nations: <3 vs 10+ years of quality schooling
  \end{itemize}
  \vspace{8pt}
  {\centering\fontsize{20}{26}\selectfont\color{amber}\bfseries Closing the gap between enrollment and actual learning\\is one of the most pressing challenges of our time.}
}

\end{tcbposter}
\end{document}

